/** Widths (px) of the WebP variants generated by scripts/images.ts. */
export const IMAGE_SIZES = {
  /** Thumbnails: card covers, gallery tiles */
  sm: 320,
  /** Mid-size: header backdrop tiles, detail background */
  md: 800,
} as const;

export type ImageSize = keyof typeof IMAGE_SIZES;

const LOCAL_ITEM_IMAGE = /^\/images\/items\/([^/]+)\.(jpe?g|png|webp)$/i;

/**
 * The resized variant of a local item image (public/images/items/*), or the
 * original src for anything else (e.g. remote images). Full-size originals
 * are still used by the lightbox.
 */
export function imageVariant(src: string, size: ImageSize): string {
  const match = LOCAL_ITEM_IMAGE.exec(src);
  return match ? `/images/generated/${size}/${match[1]}.webp` : src;
}
